"""Write ENV_REPORT.md from saved evidence runs.

    python -m learned_judgment.env.report [--artifacts artifacts/env] [--out ENV_REPORT.md]

Every status comes from the exit_code in the latest run.json of a label; a label with no run is NOT RUN.
"""
import argparse
import json
import re
import sys
from pathlib import Path

import yaml

# Acceptance criteria of 05_PERSON_A.md and the evidence label that proves each one.
CRITERIA = [
    ("Go2 policy completes every Phase 1 locomotion condition", "locomotion"),
    ("Public reset/step/finish_episode API", "world"),
    ("Unknown commands are rejected explicitly", "commands"),
    ("Fixed-seed runs reproduce robot, ball, contact and outcome data", "world"),
    ("Actual DODGE episodes log trajectories, separation, collision, fall, recovery", "dodge"),
    ("Each hidden effect switches independently and is measured", "effects"),
    ("World presets load from config.yaml", "effects"),
]
FRESH = ("Fresh Python 3.13 setup runs the documented acceptance commands", "fresh")
PACKAGES = ("mujoco", "numpy", "torch", "onnxruntime")


def _row(*cells) -> str:
    return "| " + " | ".join("" if c is None else str(c).replace("|", "\\|").replace("\n", " ") for c in cells) + " |"


def latest_runs(artifacts: Path) -> dict:
    """label -> (run dir, run.json). Stamps are fixed width, so name order is time order and the last one wins."""
    runs = {}
    for path in sorted(artifacts.glob("*/run.json")):
        match = re.fullmatch(r"\d{8}T\d{6}-([A-Za-z0-9_-]+)", path.parent.name)
        if match:
            runs[match[1]] = (path.parent, json.loads(path.read_text(encoding="utf-8")))
    return runs


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(prog="report")
    parser.add_argument("--artifacts", default="artifacts/env")
    parser.add_argument("--out", default="ENV_REPORT.md")
    args = parser.parse_args(argv)

    skills = yaml.safe_load(Path("config.yaml").read_text(encoding="utf-8"))["skills"]
    criteria = [*CRITERIA, *((f"Physics-only error and oracle noise floor: {s}", f"oracle-{s}") for s in skills), FRESH]
    runs = latest_runs(Path(args.artifacts))

    lines = [
        "# ENV_REPORT",
        "",
        f"Generated by `python -m learned_judgment.env.report` from the latest saved run of each label under "
        f"`{Path(args.artifacts).as_posix()}`. A criterion without a saved run is NOT RUN.",
        "",
        _row("Criterion", "Label", "Status", "Exit code", "Command", "Started (UTC)", "Artifacts"),
        _row(*["---"] * 7),
    ]
    for criterion, label in criteria:
        if label not in runs:
            lines.append(_row(criterion, label, "NOT RUN", None, None, None, None))
            continue
        run_dir, run = runs[label]
        status = "PASS" if run["exit_code"] == 0 else "FAIL"
        lines.append(_row(criterion, label, status, run["exit_code"], " ".join(run["command"]),
                          run.get("started_utc"), run_dir.as_posix()))

    lines += ["", "## Provenance", "", _row("Label", "Python", "Platform", "Git revision", *PACKAGES),
              _row(*["---"] * (4 + len(PACKAGES)))]
    for label in dict.fromkeys(label for _, label in criteria):
        if label in runs:
            run = runs[label][1]
            lines.append(_row(label, run.get("python"), run.get("platform"), run.get("git_rev"),
                              *(run["packages"].get(p) for p in PACKAGES)))

    Path(args.out).write_text("\n".join(lines) + "\n", encoding="utf-8")
    return 0


if __name__ == "__main__":
    sys.exit(main())
